-- V0028: Калькуляция доставки (delivery_calc) + Прайс подъём (delivery_lift) + Акт доставки (act_delivery) + Договор сборки (assembly) + Калькуляция сборки (assembly_calc) + Прайс доп.работ сборки (assembly_extra) + Акт сборки (act_assembly)

-- Калькуляция доставки (Приложение №1 к договору доставки)
UPDATE t_p24868917_kitchen_cost_calcula.doc_templates SET blocks = '[
  {"id":"hdr","type":"header","label":"Шапка","content":"Приложение № 1 к договору на оказание услуг по доставке мебели    № {{номер_договора}}  от   {{дата_договора}}","enabled":true,"align":"center"},
  {"id":"title","type":"section","label":"Заголовок","content":"«Калькуляция на выполнение услуг по доставке мебели»","enabled":true,"align":"center"},
  {"id":"table","type":"table","label":"Таблица калькуляции","content":"Наименование (перечень) работ и услуг;Ед. измерения;Количество;Цена за ед. измерения в руб.;Стоимость в руб.\nДоставка мебели в территориальных границах г. Саратова и г. Энгельса *;1 услуга;1;{{стоимость_доставки}};{{стоимость_доставки}}\nДоставка мебели за пределы территориальных границ г. Саратова и г. Энгельса**;1 км;0;70;0\n;;;Сумма:;{{стоимость_доставки}}\n;;;Скидка***:;{{стоимость_доставки}}\n;;;Сумма со скидкой:;0","enabled":true},
  {"id":"note1","type":"paragraph","label":"Примечание *","content":"*Исполнитель  вправе однократно предоставить Заказчику скидку в размере стоимости доставки, равной {{стоимость_доставки}} руб., которая осуществляется  в пределах территориальных границ г. Саратова и г. Энгельса. В случае повторной доставки, по причинам не зависящим от Исполнителя, но зависящим от Заказчика, её стоимость будет определена согласно приложению №1.","enabled":true,"align":"justify"},
  {"id":"note2","type":"paragraph","label":"Примечание **","content":"**Расчёт стоимости доставки учитывает расстояние по километражу от склада Исполнителя по адресу: г. Саратов, ул. Усть-Курдюмская д. 3, до дома (подъезда) заказчика согласно п. 1.3 договора. Километраж определяется на основании сервиса Яндекс Карты https://yandex.ru/maps/","enabled":true,"align":"justify"},
  {"id":"note3","type":"paragraph","label":"Примечание ***","content":"*** Размер скидки определяется Исполнителем индивидуально.","enabled":true,"align":"justify"},
  {"id":"sign","type":"table","label":"Подписи","content":"Подрядчик:;{{компания}};Заказчик:;{{имя_клиента}}\nМенеджер;;\n;;;\nМ.П.;;;","enabled":true}
]'::jsonb, updated_at = now()
WHERE doc_type = 'delivery_calc' AND is_default = true;

-- Прайс подъём мебели (Приложение №2 к договору доставки)
UPDATE t_p24868917_kitchen_cost_calcula.doc_templates SET blocks = '[
  {"id":"hdr","type":"header","label":"Шапка","content":"Приложение № 2 к договору на оказание услуг по доставке мебели    № {{номер_договора}}  от   {{дата_договора}}","enabled":true,"align":"center"},
  {"id":"title","type":"section","label":"Заголовок","content":"«Прайс на выполнение услуг по подъёму и заносу мебели»*","enabled":true,"align":"center"},
  {"id":"section1","type":"paragraph","label":"Заголовок таблицы 1","content":"Подъём мебели (полный комплект), при отсутствии лифта и занос мебели, при невозможности парковки автомашины вплотную к подъезду","enabled":true,"align":"center","bold":true},
  {"id":"table1","type":"table","label":"Таблица подъём полный","content":"Наименование (перечень) работ и услуг;Ед. измерения;Количество (этаж/метр);Цена за ед. измерения в руб.;Стоимость в руб.\nПодъём. Квадратура корпуса до 20 кв.м;руб/этаж;;550;0\nПодъём. Квадратура корпуса от 20 до 25 кв.м;руб/этаж;;650;0\nПодъём. Квадратура корпуса более 25 кв.м;руб/этаж;;750;0\nПеремещение мебели вручную в случае невозможности подъезда автомашины к месту разгрузки за каждые;1 м;;30;0","enabled":true},
  {"id":"section2","type":"paragraph","label":"Заголовок таблицы 2","content":"Подъём комплектующих отдельно","enabled":true,"align":"center","bold":true},
  {"id":"table2","type":"table","label":"Таблица подъём комплектующих","content":"Наименование (перечень) работ и услуг;Ед. измерения;Количество упаковок;Количество этажей;Цена за ед. измерения в руб.;Стоимость в руб.\nПодъём столешницы;1 упаковка / 1 этаж;1;9;350;3150\nПодъём стеновой панели;1 упаковка / 1 этаж;1;9;250;2250\nПодъём крупных частей корпуса. (боковины кухонного пенала, боковины шкафов-купе и т.д.). Упаковка по 2 шт.;1 упаковка / 1 этаж;;; 250;0\nПодъём длинных комплектующих (цоколь, профильная ручка, труба - целиком);1 комплект / 1 этаж;;; 60;0\nПодъём дверей-купе (Внимание! Обсудить размер лестничного пролёта, относительно размеров двери);1 дверь / 1 этаж;;; 150;0\n;;;;;Сумма: 5400","enabled":true},
  {"id":"notes","type":"paragraph","label":"Особые условия","content":"Особые условия:\n1. Если подъём мебели можно осуществить полностью на лифте - подъём бесплатный. Расчёт подъёма изделия или элементов начинается с первого этажа.\n2. Занос мебели на первый этаж – бесплатный, при условии возможности парковки автомашины вплотную к подъезду.\n3. При невозможности парковки автомашины вплотную к подъезду (не далее чем на 10 метров) к подъезду (входу в частный дом и т.д.), сумма заноса рассчитывается по данному прайсу, в зависимости от расстояния. Данный пункт распространяется на ситуации, если из-за погодных условий (снег, гололёд, размытая грунтовая дорога и т.д.) или из-за заставленного автомобилями двора (включая аналогичные ситуации) нет возможности подъехать ко входу.","enabled":true,"align":"justify"},
  {"id":"note_star","type":"paragraph","label":"Примечание","content":"* Услуги могут быть рассчитаны по факту оказания, путём отражения в акте об оказании услуг.","enabled":true,"align":"justify"},
  {"id":"sign","type":"table","label":"Подписи","content":"Подрядчик:;{{компания}};Заказчик:;{{имя_клиента}}\nМенеджер;;\n;;;\nМ.П.;;;","enabled":true}
]'::jsonb, updated_at = now()
WHERE doc_type = 'delivery_lift' AND is_default = true;

