UPDATE t_p24868917_kitchen_cost_calcula.doc_templates SET blocks = '[
  {"id":"hdr","type":"header","label":"Шапка","content":"Приложение № 3 к договору на оказание услуг по доставке мебели  № {{номер_договора}}  от   {{дата_договора}}","enabled":true,"align":"center"},
  {"id":"title","type":"section","label":"Заголовок","content":"«Акт об оказании услуг»","enabled":true,"align":"center"},
  {"id":"date_form","type":"paragraph","label":"Дата (форма)","content":"от «_____»________________ 20____г.\n(ФОРМА)","enabled":true,"align":"center"},
  {"id":"intro","type":"paragraph","label":"Преамбула","content":"{{компания}}, в лице менеджера   {{менеджер}}  действующего на основании доверенности № {{номер_доверенности}} от {{дата_доверенности}} именуемый в дальнейшем «Исполнитель» и гр.   {{имя_клиента}}\nименуемый (ая) в дальнейшем «Заказчик», с одной стороны, отдельно именуемые – «Сторона», а совместно именуемые  - «Стороны», подписали настоящий Акт об оказании услуг о нижеследующем:","enabled":true,"align":"justify"},
  {"id":"p1","type":"paragraph","label":"1 — Услуги оказаны","content":"1. В соответствии с договором на оказание услуг по доставке мебели № {{номер_договора}}  от   {{дата_договора}}  года, Исполнитель оказал, а Заказчик принял следующие услуги:\nЭтаж:  {{этаж_доставки}}   Лифт: {{примечание_доставки}}","enabled":true,"align":"justify"},
  {"id":"table_main","type":"table","label":"Таблица основных услуг","content":"Наименование (перечень) работ и услуг;Ед. измерения;Количество;Цена за ед. измерения в руб.;Стоимость в руб.\nДоставка мебели в территориальных границах г. Саратова и г. Энгельса;1 услуга;1;0;0\nДоставка мебели за пределы территориальных границ г. Саратова и г. Энгельса;1 км;0;70;0","enabled":true},
  {"id":"section_add","type":"paragraph","label":"Заголовок доп.услуг","content":"Дополнительные услуги, по факту оказания","enabled":true,"align":"center","bold":true},
  {"id":"table_lift","type":"table","label":"Таблица подъёма","content":"Подъём мебели (полный комплект), при отсутствии лифта и занос мебели, при невозможности парковки автомашины вплотную к подъезду;;;;\nНаименование (перечень) работ и услуг;Ед. измерения;Количество (этаж/метр);Цена за ед. измерения в руб.;Стоимость в руб.\nПодъём. Квадратура корпуса до 20 кв.м;руб/этаж;;550;\nПодъём. Квадратура корпуса от 20 до 25 кв.м;руб/этаж;;650;\nПодъём. Квадратура корпуса более 25 кв.м;руб/этаж;;750;\nПеремещение мебели вручную в случае невозможности подъезда автомашины к месту разгрузки за каждые;1 м;;30;","enabled":true},
  {"id":"table_parts","type":"table","label":"Таблица комплектующих","content":"Подъём комплектующих отдельно;;;;\nНаименование (перечень) работ и услуг;Ед. измерения;Количество упаковок;Количество этажей;Цена за ед. измерения в руб.;Стоимость в руб.\nПодъём столешницы;1 упаковка / 1 этаж;;;350;\nПодъём стеновой панели;1 упаковка / 1 этаж;;;250;\nПодъём крупных частей корпуса. (боковины кухонного пенала, боковины шкафов-купе и т.д.). Упаковка по 2 шт.;1 упаковка / 1 этаж;;;250;\nПодъём длинных комплектующих (цоколь, профильная ручка, труба - целиком);1 комплект / 1 этаж;;;60;\nПодъём дверей-купе;1 дверь / 1 этаж;;;150;\n;;;;;Цена услуг составляет:","enabled":true},
  {"id":"p2","type":"paragraph","label":"2 — Оплата доп.услуг","content":"2. Дополнительные услуги, оказанные исполнителем: оплачены / не оплачены (ненужное зачеркнуть).\n3. Услуги по договору оказаны Исполнителем полностью, своевременно и надлежащим образом. Заказчик претензий к Исполнителю: не имеет / имеет (ненужное зачеркнуть).","enabled":true,"align":"justify"},
  {"id":"lines1","type":"lines","label":"Линии для замечаний","content":"3","enabled":true},
  {"id":"p4","type":"paragraph","label":"4–5","content":"4. В случае наличия замечаний Заказчик, после подписания акта, вправе требовать устранения замечаний, отражённых в данном акте.\n5. Настоящий акт подписан в 2 (двух) экземплярах по одному для каждой из Сторон.","enabled":true,"align":"justify"},
  {"id":"sign","type":"table","label":"Подписи","content":"Подрядчик:;{{компания}};Заказчик:;{{имя_клиента}}\nМенеджер;;\n;;;\nМ.П.;;;","enabled":true}
]'::jsonb, updated_at = now()
WHERE doc_type = 'act_delivery' AND is_default = true;

-- Договор сборки (assembly) — полный текст
UPDATE t_p24868917_kitchen_cost_calcula.doc_templates SET blocks = '[
  {"id":"hdr","type":"header","label":"Шапка","content":"ДОГОВОР\nна выполнение работ по монтажу и сборке мебели  № {{номер_договора}}\nг. {{город}}                                                                                   {{дата_договора}}","enabled":true,"align":"center"},
  {"id":"intro","type":"paragraph","label":"Преамбула","content":"{{компания}}, в лице менеджера  {{менеджер}}  действующего на основании доверенности № {{номер_доверенности}} от {{дата_доверенности}} именуемый в дальнейшем «Подрядчик» и гр.   {{имя_клиента}}\nименуемый (ая) в дальнейшем «Заказчик», действующий (ая) как физическое лицо, с одной стороны, отдельно именуемые – «Сторона», а совместно именуемые  - «Стороны», заключили настоящий Договор о нижеследующем:","enabled":true,"align":"justify"},
  {"id":"s1","type":"section","label":"1. ПРЕДМЕТ ДОГОВОРА","content":"1. ПРЕДМЕТ ДОГОВОРА","enabled":true,"align":"center"},
  {"id":"s1p1","type":"paragraph","label":"1.1","content":"1.1. Подрядчик обязуется выполнить работу по монтажу и сборке мебели (далее – Работы), приобретённой у ООО «Интерьерные решения» согласно договору бытового подряда на изготовление мебели № {{номер_договора}}  от   {{дата_договора}}  года, а Заказчик обязуется принять и оплатить результат Работ.\nВ перечень Работ входит: распаковка, расстановка в порядке и месте, определённом Заказчиком, и сборка мебели в соответствии с инструкциями, схемами и иной технической документацией, в помещении.\nВ перечень Работ не включаются сантехнические работы (установка смесителей, сифонов, кранов и т.д.), электромонтажные работы, а также работы по подключению плит, духовок, стиральных и посудомоечных машин, вытяжек и другой бытовой техники.\nПодключение бытовой техники, приобретённой Заказчиком вместе с мебелью, осуществляют сервисные центры на основании своих расценок.","enabled":true,"align":"justify"},
  {"id":"s1p2","type":"paragraph","label":"1.2","content":"1.2. Работы выполняются по адресу:      {{адрес_доставки}}","enabled":true,"align":"justify"},
  {"id":"s2","type":"section","label":"2. СТОИМОСТЬ И РАСЧЁТЫ","content":"2. СТОИМОСТЬ РАБОТ И ПОРЯДОК РАСЧЁТОВ","enabled":true,"align":"center"},
  {"id":"s2p1","type":"paragraph","label":"2.1","content":"2.1. Общая стоимость работ, определяется на основании Приложений №1 и №2 к настоящему договору, НДС не облагается на основании ст. 346.11 НК РФ и указывается в Акте выполненных работ за фактически выполненные Подрядчиком работы.","enabled":true,"align":"justify"},
  {"id":"s2p2","type":"paragraph","label":"2.2","content":"2.2. Оплата работ осуществляется в следующем порядке: 100 % предоплата безналичным расчётом на счёт Подрядчика либо наличными денежными средствами в кассу Подрядчика.","enabled":true,"align":"justify"},
  {"id":"s2p3","type":"paragraph","label":"2.3","content":"2.3. Обязательство Заказчика по безналичной оплате считается исполненным в момент зачисления денежных средств на счёт Подрядчика, указанный в реквизитах.","enabled":true,"align":"justify"},
  {"id":"s2p4","type":"paragraph","label":"2.4","content":"2.4. В случае недокомплекта дополнительной фурнитуры, материалов и т.д., приобретённых Заказчиком самостоятельно, препятствующего окончанию выполнения Работ, все последующие выезды Подрядчика оплачиваются в размере 2000,00 (две тысячи) рублей. Дополнительная оплата осуществляется Заказчиком в срок не позднее 1 (одного) рабочего дня до предполагаемой и согласованной Сторонами даты выполнения Работ.","enabled":true,"align":"justify"},
  {"id":"s3","type":"section","label":"3. СРОКИ ВЫПОЛНЕНИЯ РАБОТ","content":"3. СРОКИ И ПОРЯДОК ВЫПОЛНЕНИЯ РАБОТ","enabled":true,"align":"center"},
  {"id":"s3p","type":"paragraph","label":"3.1–3.11","content":"3.1. Работы по договору выполняются в течение {{срок_сборки}} ({{срок_сборки_прописью}}) рабочих дней со дня доставки мебели Заказчику, при условии получения от Заказчика предварительной оплаты по Договору и предварительного согласования Заказчика.\n3.2. Стороны согласовывают дату и время проведения Работ путём обмена сообщениями по электронной почте или обмена сообщениями (WhatsApp, Telegram, СМС и т.д.) на телефонный номер Сторон согласно реквизитам, указанным в Договоре.\n3.3. В случае, если в период выполнения Работ будут выявлены недостатки элементов мебели и иных изделий, которые необходимо устранить, то срок выполнения Работ увеличен на срок устранения недостатков. Если такие недостатки возникли в результате действий Заказчика и/или третьих лиц, не имеющих отношения к ООО «Интерьерные решения», то устранение недостатков осуществляется за счёт Заказчика.\n3.4. В случае, если Заказчик переносит дату выполнения Работ, то срок выполнения Работ будет увеличен.\n3.5. В случае проведения Заказчиком и/или иными лицами строительных, ремонтных и иных работ в помещении, в котором необходимо выполнить Работы, а также в случае не освобождения помещения от строительного и иного мусора к согласованной Сторонами дате и времени, срок выполнения Работ будет увеличен, при этом Подрядчик не будет считаться просрочившим свои обязательства по срокам выполнения Работ и не будет нести никакой ответственности за нарушение условий и сроков по настоящему Договору.\n3.6. Подрядчик выполняет Работы в рабочие дни с 09:00 до 21:00 часов, в выходные дни с 10:00 до 19:00 часов. Перерыв с 13:00 до 15:00 часов.\n3.7. Окончанием Работ является день, когда Сторонами подписан Акт выполненных Работ.\n3.8. Подрядчик оставляет за собой право не приступать к исполнению обязательств по настоящему Договору или приостановить исполнение обязательств до получения им суммы предварительной оплаты. При этом срок выполнения Работ автоматически продлевается на период просрочки оплаты, допущенной Заказчиком.\n3.9. При выполнении Работ в помещении Заказчика Подрядчик имеет право проводить работы с использованием электроинструмента. Проводимые в процессе монтажа работы неизбежно сопряжены с шумом, образованием пыли и стружки материала, а также выделением характерных запахов.\n3.10. В случае невозможности надлежащей установки мебели в связи с неровностью поверхности (пола, стен, потолков) в помещении Заказчика, Заказчик обязан самостоятельно устранить эти недостатки.\n3.11. При установке мебели в неподготовленном помещении допускается отклонение от первоначальной конструкции, то есть появление зазоров и т.д. Подрядчик не несёт ответственности за геометрию стен, пола и потолка Заказчика.","enabled":true,"align":"justify"},
  {"id":"s4","type":"section","label":"4. ОБЯЗАННОСТИ СТОРОН","content":"4. ОБЯЗАННОСТИ СТОРОН","enabled":true,"align":"center"},
  {"id":"s4p1","type":"paragraph","label":"4.1 — Подрядчик обязан","content":"4.1. Подрядчик обязан:\n4.1.2. Приступить к выполнению Работ в срок установленные в п. 3.1. Договора.\n4.1.3. Предупредить Заказчика о возможных неблагоприятных последствиях выполнения его указаний о способе исполнения работы, а также иных не зависящих от Подрядчика обстоятельствах, которые грозят годности или прочности результатов выполняемой работы либо создают невозможность её завершения в срок.","enabled":true,"align":"justify"},
  {"id":"s4p2","type":"paragraph","label":"4.2 — Заказчик обязан","content":"4.2. Заказчик обязан:\n4.2.1. Принять и оплатить выполненную Подрядчиком Работу на условиях и в порядке, предусмотренных Договором.\n4.2.2. Присутствовать при выполнении Работ, либо обеспечить присутствие своего представителя, который уполномочен подписывать Акт выполненных работ. Заказчик предварительно уведомляет Подрядчика об уполномоченном представителе.\n4.2.3. Обеспечить бесплатной парковкой автомобиль Подрядчика на период выполнения Работ по адресу, указанному в п. 1.2. Договора. В случае, если парковка по адресу платная, то парковка оплачивается Заказчиком.\n4.2.4. Закончить все ремонтные и иные работы в помещении, в котором будут выполнены Работы, а также освободить данное помещение от строительного и иного мусора.\n4.2.5. Подготовить помещение для выполнения работ по монтажу:\n- укрыть во избежание порчи мебель, пол, бытовые приборы,\n- убрать лишние предметы, на время проведения работ должны быть удалены все посторонние лица, а также домашние животные.\n- обеспечить в помещении наличие освещения и электричества 220В.\n- температура воздуха в помещении должна быть в пределах от +10 до +25 град.С;\n- относительная влажность воздуха в помещении должна быть в пределах от 45 до 75 %.\n- полы должны быть выполнены с уклоном не более 3 мм уклона на 1 метр пола;\n- стены, полы и потолки должны быть выровнены и составлять между собой угол 90 градусов;\n- стены должны быть приспособлены для крепления мебели.\n4.2.6. Предоставлять Подрядчику информацию, необходимую для выполнения Работ по Договору.","enabled":true,"align":"justify"},
  {"id":"s4p3","type":"paragraph","label":"4.3 — Подрядчик вправе","content":"4.3. Подрядчик вправе:\n4.3.1. Требовать своевременного подписания Заказчиком Акта выполненных работ.\n4.3.2. Требовать своевременной оплаты Работ в соответствии с пунктом 2.2. Договора.\n4.3.3. Запрашивать у Заказчика разъяснения и уточнения относительно порядка выполнения Работ.\n4.3.4. Привлекать третьих лиц для исполнения обязательств по настоящему Договору. Подрядчик несёт ответственность за действия/бездействие третьих лиц, выполняющих Работу по Договору, как за свои собственные.\n4.3.5. Не приступать к Работе, а начатую Работу приостановить в случаях, когда нарушение Заказчиком своих обязанностей, установленных в п. 4.2 Договора препятствует исполнению Договора, а также при наличии обстоятельств, очевидно свидетельствующих о том, что исполнение указанных обязанностей не будет произведено в установленный срок.\n4.3.6. Самостоятельно определить количество специалистов, необходимых для выполнения работ, график работы, а также сроки в зависимости от сложности Изделия.\n4.4. Заказчик вправе:\n4.4.1. Требовать от Подрядчика надлежащего исполнения обязательств в соответствии с Договором, а также требовать своевременного устранения выявленных недостатков при приёмке Работ.\n4.4.2. Отозвать согласие на обработку своих персональных данных Подрядчиком.","enabled":true,"align":"justify"},
  {"id":"s5","type":"section","label":"5. ПОРЯДОК СДАЧИ-ПРИЁМКИ","content":"5. ПОРЯДОК СДАЧИ-ПРИЁМКИ РАБОТ","enabled":true,"align":"center"},
  {"id":"s5p","type":"paragraph","label":"5.1–5.3","content":"5.1. По завершении выполнения работ Подрядчик предоставляет Заказчику результаты выполненных работ и Акт выполненных работ, который Заказчик утверждает в день выставления Акта либо даёт мотивированный отказ от приёмки работ в тот же срок.\n5.2. В день окончания выполнения Подрядчиком Работ Стороны (их уполномоченные представители) подписывают Акт выполненных работ, в соответствии с которым Подрядчик передаёт, а Заказчик принимает Работы и их результат – партию собранной и смонтированной мебели. В случае наличия у Заказчика замечаний к качеству Работ, Заказчик обязан подписать указанный в настоящем пункте Акт выполненных работ. После подписания Акта выполненных работ Подрядчик не принимает претензий по качеству выполненных работ.\n5.3. При необоснованном отказе одной из сторон от подписания акта в нём делается отметка об этом и акт подписывается другой стороной в одностороннем порядке, работы считаются выполненными на день подписания такого Акта одной из сторон.","enabled":true,"align":"justify"},
  {"id":"s6","type":"section","label":"6. ОТВЕТСТВЕННОСТЬ","content":"6. ОТВЕТСТВЕННОСТЬ СТОРОН","enabled":true,"align":"center"},
  {"id":"s6p","type":"paragraph","label":"6.1–6.3","content":"6.1. Стороны несут ответственность за неисполнение или ненадлежащее исполнение своих обязательств по Договору в соответствии с Законом Российской Федерации от 7 февраля 1992 г. № 2300-1 «О защите прав потребителей» и иными правовыми актами, принятыми в соответствии с ним.\n6.2. За нарушение сроков оплаты Подрядчик вправе потребовать от Заказчика уплаты неустойки (пени) за каждый день просрочки в размере 0,1 % от суммы задолженности.\n6.3. Подрядчик не несёт ответственности за невыполнение обязательств по Договору, если оно вызвано неисполнением соответствующих обязанностей Заказчика.","enabled":true,"align":"justify"},
  {"id":"s7","type":"section","label":"7. СПОРЫ","content":"7. ПОРЯДОК РАЗРЕШЕНИЯ СПОРОВ","enabled":true,"align":"center"},
  {"id":"s7p","type":"paragraph","label":"7.1–7.3","content":"7.1. Все споры или разногласия, возникающие между Сторонами по настоящему Договору или в связи с ним, разрешаются путём переговоров между ними.\n7.2. До передачи спора на рассмотрение суда Стороны предусматривают обязательный претензионный порядок урегулирования разногласий. Направление претензии возможно по электронной почте, путём обмена сообщениями (Telegram, WhatsApp, СМС и т.д.) на телефонный номер Сторон согласно реквизитам, указанным в Договоре. Срок ответа на претензию Сторон устанавливают в 10 (Десять) рабочих дней с момента получения претензии заинтересованной Стороны.\n7.3. В случае невозможности разрешения разногласий путём переговоров споры или разногласия, возникающие между Сторонами по настоящему Договору или в связи с ним, решаются в судебном порядке по месту нахождения Подрядчика.","enabled":true,"align":"justify"},
  {"id":"s8","type":"section","label":"8. СРОК ДЕЙСТВИЯ","content":"8. СРОК ДЕЙСТВИЯ ДОГОВОРА","enabled":true,"align":"center"},
  {"id":"s8p","type":"paragraph","label":"8.1–8.4","content":"8.1. Договор вступает в силу с момента его подписания обеими Сторонами и действует до полного исполнения Сторонами принятых на себя обязательств.\n8.2. Изменения и дополнения к Договору принимаются по обоюдному соглашению Сторон, путём подписания Дополнительного соглашения к Договору.\n8.3. Договор может быть расторгнут досрочно по письменному соглашению Сторон, в одностороннем порядке в случаях, предусмотренных действующим законодательством Российской Федерации.\n8.4. В случае одностороннего отказа Заказчика от Договора Заказчик обязуется, оплатить Подрядчику фактически понесённые им расходов, связанных с исполнением обязательств по данному Договору.","enabled":true,"align":"justify"},
  {"id":"s9","type":"section","label":"9. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ","content":"9. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ","enabled":true,"align":"center"},
  {"id":"s9p","type":"paragraph","label":"9.1–9.4","content":"9.1. Договор вступает в силу с момента его подписания Сторонами и действует до полного исполнения Сторонами всех принятых на себя обязательств.\n9.2. При заключении Договора и подписания других документов в рамках его исполнения, Стороны согласны на факсимильное воспроизведение подписи («факсимиле»), уполномоченных лиц, а также на обмен электронными копиями документов. Стороны признают юридически значимой переписку между сторонами по электронной почте, а также переписку по номеру телефона, указанному в настоящем договоре в любых приложениях для обмена сообщениями (Viber, WhatsApp, Telegram, СМС и т.д.). Направленные таким образом документы считаются подписанными простой электронной подписью и признаются Сторонами равнозначными бумажным, подписанным собственноручной подписью Сторон.\n9.3. Стороны признают юридическую силу всех документов, требований, уведомлений, претензий, извещений, оформленных должным образом и направленных друг другу в электронном виде по указанным адресам электронной почты и телефонам во исполнение настоящего Договора. Стороны договорились, что сообщение при такой форме коммуникации считается доставленным тогда, когда приложение, через которое производится коммуникация подтверждает факт направления сообщения через свой внутренний интерфейс. При этом и Заказчик, и Подрядчик обязуются регулярно просматривать указанные источники коммуникации. Стороны договорились, что сообщение считается доставленным и в тех случаях, если оно поступило лицу, которому оно направлено, но по обстоятельствам, зависящим от него, не было ему вручено или адресат не ознакомился с ним.\n9.4 Заказчик даёт своё согласие на обработку своих персональных данных, а именно: на действия, совершаемые с использованием средств автоматизации или без использования таких средств, включая сбор, запись, систематизацию, накопление, хранение, уточнение (обновление, изменение), извлечение, использование, передачу (распространение, предоставление, доступ), обезличивание, блокирование, удаление, уничтожение его  персональных данных, Обществу с ограниченной ответственностью «ИНТЕРЬЕРНЫЕ РЕШЕНИЯ» (ОГРН: {{огрн}}, ИНН: {{инн}}), расположенному по адресу: 410018, Российская Федерация, Саратовская область, Саратов г., Усть-Курдюмская, 3 помещение 1.\nЦель обработки персональных данных: исполнение настоящего договора. Заказчик даёт своё согласие на использование следующих персональных данных: фамилия, имя, отчество, паспортные данные, адрес места жительства, фотографии изделий на объекте Заказчика; номер телефона, адрес электронной почты. Согласие предоставляется на срок действия настоящего договора, а после прекращения договора - в течение 12 месяцев с даты подписания Сторонами акта сдачи-приёмки выполненных Работ.\nНастоящее условие договора может быть изменено Заказчиком - субъектом персональных данных, в любой момент в одностороннем порядке путём отзыва согласия на обработку персональных данных. Отзыв согласия на обработку персональных данных осуществляется посредством составления письменного документа, который может быть направлен в адрес Подрядчика почтовым отправлением с уведомлением о вручении, либо вручён лично под расписку представителю Подрядчика.","enabled":true,"align":"justify"},
  {"id":"s9_sign","type":"paragraph","label":"Подпись","content":"_________________________                    /                                                                   /\n             (подпись)                                           (расшифровка подписи от руки)","enabled":true,"align":"left"},
  {"id":"s9_apps","type":"paragraph","label":"9.5 — Приложения","content":"9.5. К настоящему Договору прилагаются и являются неотъемлемой частью следующие приложения:\n1. Калькуляция на выполнение работ по сборке мебели.\n2. Прайс на дополнительные работы.\n3. Образец Акта выполненных работ.","enabled":true,"align":"justify"},
  {"id":"s10","type":"section","label":"10. РЕКВИЗИТЫ СТОРОН","content":"10. РЕКВИЗИТЫ СТОРОН","enabled":true,"align":"center"},
  {"id":"s10_exec","type":"paragraph","label":"Реквизиты подрядчика","content":"Подрядчик:\n{{компания}}\nИНН/КПП: {{инн_кпп}}\nОГРН: {{огрн}}\nЮридический и фактический адрес: {{адрес_компании}}\nБанковские реквизиты:\n{{банк}}\nБИК: {{бик}}\nРас/с: {{расчётный_счёт}}\nКорп/с: {{корр_счёт}}\nТелефон: {{телефон_компании}}\nE-mail: {{email_компании}}\n\nМенеджер:\n{{менеджер}}\n\n_________________________          _________________________\n                                                    М.П.","enabled":true,"align":"left"},
  {"id":"s10_client","type":"paragraph","label":"Реквизиты заказчика","content":"Заказчик:\n{{имя_клиента}}\nПаспорт. Серия, номер:\n{{паспорт}}\nКем выдан:\n{{паспорт_выдан}}\n\nАдрес прописки:\n{{адрес_регистрации}}\n\nТелефон:\n{{телефон_клиента}}\nПредпочитаемый канал обмена сообщениями:\n{{мессенджер}}\n\n_________________________","enabled":true,"align":"left"}
]'::jsonb, updated_at = now()
WHERE doc_type = 'assembly' AND is_default = true;

-- Калькуляция сборки (Приложение №1 к договору сборки)
UPDATE t_p24868917_kitchen_cost_calcula.doc_templates SET blocks = '[
  {"id":"hdr","type":"header","label":"Шапка","content":"Приложение № 1 к договору на выполнение работ по монтажу и сборке мебели  № {{номер_договора}}  от   {{дата_договора}}","enabled":true,"align":"center"},
  {"id":"title","type":"section","label":"Заголовок","content":"«Калькуляция на выполнение работ по сборке мебели»","enabled":true,"align":"center"},
  {"id":"table","type":"table","label":"Таблица калькуляции","content":"Наименование (перечень) работ и услуг;Ед. измерения;Количество;Цена за ед. измерения в руб.;Стоимость в руб.\nСборка и монтаж мебели согласно договору бытового подряда на изготовление мебели  № {{номер_договора}}  от  {{дата_договора}} *;работа;1;{{стоимость_сборки}};{{стоимость_сборки}}\nВыезд сборщика за пределы территориальных границ г. Саратова и г. Энгельса**;1 км;0;40;0\n;;;Сумма:;{{стоимость_сборки}}\n;;;Скидка***:;{{стоимость_сборки}}\n;;;Сумма со скидкой:;0","enabled":true},
  {"id":"note1","type":"paragraph","label":"Примечание *","content":"*Подрядчик  вправе однократно предоставить Заказчику скидку в размере стоимости сборки, равной {{стоимость_сборки}} руб., которая осуществляется  в пределах территориальных границ г. Саратова и г. Энгельса. В случае повторного выезда к месту сборки, по причинам не зависящим от Подрядчика, но зависящим от Заказчика, её стоимость будет определена согласно приложению №1.","enabled":true,"align":"justify"},
  {"id":"note2","type":"paragraph","label":"Примечание **","content":"**Расчёт стоимости выезда сборщика учитывает расстояние по километражу от склада Подрядчика по адресу: г. Саратов, ул. Усть-Курдюмская д. 3, до дома (подъезда) заказчика согласно п. 1.2 договора. Километраж определяется на основании сервиса Яндекс Карты https://yandex.ru/maps/","enabled":true,"align":"justify"},
  {"id":"note3","type":"paragraph","label":"Примечание ***","content":"*** Размер скидки определяется Подрядчиком индивидуально.","enabled":true,"align":"justify"},
  {"id":"sign","type":"table","label":"Подписи","content":"Подрядчик:;{{компания}};Заказчик:;{{имя_клиента}}\nМенеджер;;\n;;;\nМ.П.;;;","enabled":true}
]'::jsonb, updated_at = now()
WHERE doc_type = 'assembly_calc' AND is_default = true;

-- Прайс дополнительных работ сборки (Приложение №2 к договору сборки)
UPDATE t_p24868917_kitchen_cost_calcula.doc_templates SET blocks = '[
  {"id":"hdr","type":"header","label":"Шапка","content":"Приложение № 2 к договору на выполнение работ по монтажу и сборке мебели    № {{номер_договора}}  от   {{дата_договора}}","enabled":true,"align":"center"},
  {"id":"title","type":"section","label":"Заголовок","content":"«Прайс на дополнительные работы»*","enabled":true,"align":"center"},
